from ta_pcmd.submodule_ute_common_abstract_core.message import NotFoundKey


def get_all_reports_with_field(field_name, pcmd_reports):
    ''' to be added '''
    reports_with_field = []
    for report in pcmd_reports:
        try:
            report.get_all_values_by_key(field_name)
        except NotFoundKey:
            continue
        else:
            reports_with_field.append(report)
    return reports_with_field


def get_all_reports_with_field_set_to_value(field_name, field_value, pcmd_reports):
    ''' to be added '''
    reports_with_field_set_to_value = []
    for report in pcmd_reports:
        try:
            single_report_field_values = report.get_all_values_by_key(field_name)
        except NotFoundKey:
            continue
        else:
            if field_value in single_report_field_values:
                reports_with_field_set_to_value.append(report)
    return reports_with_field_set_to_value


def get_sum_of_field_values_from_pcmd_reports(field_name, pcmd_reports):
    ''' to be added '''
    return sum(map(int, get_all_field_values_from_pcmd_reports(field_name, pcmd_reports)))


def get_unique_field_values_from_pcmd_reports(field_name, pcmd_reports):
    ''' to be added '''
    return set(get_all_field_values_from_pcmd_reports(field_name, pcmd_reports))


def get_all_field_values_from_pcmd_reports(field_name, pcmd_reports):
    ''' to be added '''
    field_values = []
    for report in pcmd_reports:
        try:
            single_report_field_values = report.get_all_values_by_key(field_name)
        except NotFoundKey:
            continue
        else:
            field_values.extend(single_report_field_values)
    return field_values


def format_crnti_based_on_technology(crnti, technology):
    ''' to be added '''
    if technology == '4G':
        return format_crnti_to_hex(crnti)
    if technology == '5G':
        return format_crnti_to_int(crnti)


def format_crnti_to_int(crnti):
    ''' to be added '''
    if ':' in crnti:
        crnti = crnti.replace(':', '')
        crnti = int(crnti, 16)
    return str(crnti)


def format_crnti_to_hex(crnti):
    ''' to be added '''
    if ':' not in crnti:
        crnti = '{:04x}'.format(int(crnti))
        crnti = crnti[0:2] + ':' + crnti[2:4]
    return crnti
